W = '[[w.lich-su-khang-chien-chong-my]]'
MP = 'Made public: 2013.'
def add(id, when, date, c, n, tags, also=None):
    e = {'id': id, 'when': when, 'date': date, 'thread': 'vietnam-hanoi'}
    if also: e['also'] = also
    e['c'] = c; e['n'] = n; e['tags'] = ['polity:drv'] + tags
    return {'add': {'entry': e}}
def cite(id, item, units): return {'cite': {'id': id, 'item': item, 'units': units}}
def var(id, unit, reads, at): return {'variant': {'id': id, 'unit': unit, 'witness': 'w.lich-su-khang-chien-chong-my', 'reads': reads, 'at': at}}
def chk(id, text): return {'check': {'id': id, 'text': text}}

